window.__votdWeek && window.__votdWeek({"week":"2028-03-27","reading":"Jacob 5–7","days":[{"d":"2028-03-27","ref":"Jacob 5:3","b":"Jacob","c":5,"v":3,"he":"כִּי־כֹה אָמַר יְהוָה אֲדַמֶּה אוֹתְךָ בֵּית־יִשְׂרָאֵל לְזַיִת תַּרְבּוּת אֲשֶׁר לָקַח אִישׁ וַיְטַפְּחֵהוּ בְּכַרְמוֹ וַיִּגְדַּל וַיִּזְקַן וַיָּחֶל לִנְבֹל׃","en":"For behold, thus saith the Lord, I will liken thee, O house of Israel, like unto a tame olive tree, which a man took and nourished in his vineyard; and it grew, and waxed old, and began to decay."},{"d":"2028-03-28","ref":"Jacob 5:26","b":"Jacob","c":5,"v":26,"he":"וַיְהִי כִּי אָמַר אֲדוֹן הַכֶּרֶם אֶל־הָעֶבֶד קְטֹף אֶת־הָעֲנָפִים אֲשֶׁר לֹא הוֹצִיאוּ פְּרִי טוֹב וְהַשְׁלִיכֵם אֶל־הָאֵשׁ׃","en":"And it came to pass that the Lord of the vineyard said unto the servant: Pluck off the branches that have not brought forth good fruit, and cast them into the fire."},{"d":"2028-03-29","ref":"Jacob 6:3","b":"Jacob","c":6,"v":3,"he":"וּמַה־מְאֻשָּׁרִים הֵם אֲשֶׁר עָבְדוּ בְּכׇל־כֹּחָם בְּכַרְמוֹ וּמַה־אֲרוּרִים הֵם אֲשֶׁר יֻשְׁלְכוּ אֶל־מְקוֹמָם וְיִשָּׂרֵף הָעוֹלָם בָּאֵשׁ׃","en":"And how blessed are they who have labored diligently in his vineyard; and how cursed are they who shall be cast out into their own place! And the world shall be burned with fire."},{"d":"2028-03-30","ref":"Jacob 6:7","b":"Jacob","c":6,"v":7,"he":"כִּי הִנֵּה אַחֲרֵי אֲשֶׁר טֻפַּחְתֶּם בִּדְבַר אֱלֹהִים הַטּוֹב כׇּל־הַיּוֹם הֲתוֹצִיאוּ פְּרִי רַע לְמַעַן תִּכָּרְתוּ וְתֻשְׁלְכוּ אֶל־הָאֵשׁ׃","en":"For behold, after ye have been nourished by the good word of God all the day long, will ye bring forth evil fruit, that ye must be hewn down and cast into the fire?"},{"d":"2028-03-31","ref":"Jacob 6:12","b":"Jacob","c":6,"v":12,"he":"הוֹי הֱיוּ חֲכָמִים מַה־עוֹד אוּכַל לֵאמֹר׃","en":"O be wise; what can I say more?"},{"d":"2028-04-01","ref":"Jacob 7:11","b":"Jacob","c":7,"v":11,"he":"וָאֹמַר אֵלָיו אִם־כֵּן לֹא הֲבִינוֹתָ אוֹתָם כִּי הֵם מְעִידִים בֶּאֱמֶת עַל־הַמָּשִׁיחַ הִנֵּה אֹמֵר לְךָ כִּי־לֹא כָּתְבוּ הַנְּבִיאִים וְלֹא נִבְּאוּ בִּלְתִּי אִם־דִּבְּרוּ עַל־הַמָּשִׁיחַ הַזֶּה׃","en":"And I said unto him: Then ye do not understand them; for they truly testify of Christ. Behold, I say unto you that none of the prophets have written, nor prophesied, save they have spoken concerning this Christ."},{"d":"2028-04-02","ref":"Jacob 7:20","b":"Jacob","c":7,"v":20,"he":"וַיְהִי כַּאֲשֶׁר דִּבֶּר אֶת־הַדְּבָרִים הָאֵלֶּה לֹא־יָכֹל לְדַבֵּר עוֹד וַיִּגְוַע׃","en":"And it came to pass that when he had said these words he could say no more, and he gave up the ghost."}]});
